import {
  DEFAULT_DISPLAY_PROFILE, DEFAULT_INPUT_MAPPING, parseGameProfile,
  unknownRightsRecord, type EvidenceRecord, type GameProfile, type RightsRecord
} from "@rgme/core";

/**
 * Bundled demonstrator: the "RGME PAL Test Pattern". It is generated by the MockRuntimeAdapter
 * and contains no third-party game data. Only local execution is evidenced; everything else
 * stays unknown, so export/redistribution remains blocked (unknown never becomes permission).
 */
const SHA = "0".repeat(63) + "1"; // synthetic id: there is no real ADF behind the demo

export const DEMO_PROFILE: GameProfile = parseGameProfile({
  schema: "rgme.game/v0.2",
  id: "rgme-demo-pal-test-pattern",
  title: "RGME PAL Test Pattern (Demo)",
  platform: "amiga",
  machine: { model: "A500", chipset: "OCS", video: "PAL", ram: { chipKb: 512, fastKb: 512 } },
  media: [{ id: "df0", kind: "adf", filename: "rgme-demo.adf", label: "RGME Demo", sha256: SHA }],
  runtime: { preferredAdapter: "mock" },
  launch: { bootMediaId: "df0", autoStart: true },
  input: DEFAULT_INPUT_MAPPING,
  display: DEFAULT_DISPLAY_PROFILE,
  rights: { recordId: "rights:rgme-demo-pal-test-pattern" }
});

export const DEMO_EVIDENCE: EvidenceRecord = {
  schema: "rgme.evidence/v0.2",
  id: "ev:rgme-demo:authored",
  subject: { type: "game", id: DEMO_PROFILE.id },
  claim: "Demo content is generated by RGME itself; no third-party game data is involved.",
  source: { type: "author", title: "RGME project" },
  confidence: "verified",
  createdAt: "2026-11-05T00:00:00Z"
};

export const DEMO_RIGHTS: RightsRecord = {
  ...unknownRightsRecord(DEMO_PROFILE.id, "2026-11-05T00:00:00Z"),
  id: DEMO_PROFILE.rights.recordId,
  assertions: [
    { action: "private_execution", component: "game_binary", status: "permitted", evidenceIds: [DEMO_EVIDENCE.id], confidence: "verified" }
  ],
  notes: ["Local playback evidenced; redistribution rights not asserted."]
};
